          "mondai": 10,
          "mondaiName": "問題10：短文読解 (Đoản văn 3 - Đề 7/2018)",
          "passage": "言うまでもなく（注1）、深く思考した者は競争相手より有利な立場に立てる。しかし行動を止めてまでして考えるのは避けよう。行動があなたの思考を止めることはない。むしろ思考を加速させ、改善させる効果があることを知ってほしい。\n行動し、変化する状況の中で考えつづけることを実践するのはかなり勇気が要るだろう。予期しないことが起こるかもしれない。リスク（注2）もある。しかし、そうすることで最速の思考が生み出されるのだ。\n（注1）言うまでもなく：わざわざ言う必要もないが\n（注2）リスク：危険",
          "sentence": "筆者の考えに合うのはどれか。",
