          "passage": "2018年4月2日\n社員各位\n定期健康診断について\nこれまで定期健康診断は毎年9月にアラキ医療センターで実施してきましたが、今年度より各自で指定の医療機関の中から選んで受診していただくことになりました。4月から翌年3月までの間で受診日を決め、直接医療機関に予約を入れて受診するようにしてください。なお、検査項目につきましては、これまで通りです。\n指定機関と予約方法の詳細は、後日お配りする資料でご確認ください。\nどうぞよろしくお願いいたします。\n以上",
