          "mondaiName": "問題10：短文読解 (Đoản văn 5 - Đề 7/2018)",
          "passage": "成功例にできるだけ忠実に（注1）従って努力すれば、やみくもに（注2）努力するよりも、成功する確率はかなり高い。もちろん、人の成功を見て、それを全面的に「真似る」のは、アイデアを盗んだとか、猿真似をしたとかいわれて、非難されても仕方がない。\nしかしながら、人のいいところを参考にして、自分なりの方法を工夫して努力していくのは、まともな（注3）人のすることである。そこには、単に真似るのではなく、先達（注4）から「学ぶ」という姿勢がある。\n（注1）忠実に：ここでは、正確に\n（注2）やみくもに：ここでは、何も考えずに、ただ\n（注3）まともな：ここでは、常識のある\n（注4）先達：先輩",
