          "id": 114,
          "mondai": 11,
          "mondaiName": "問題11：中文読解 (Trung văn 1 - Ruộng lúa Aotakaze)",
          "passage": "水田にはたくさんの生き物がいます。水田の土に含まれる栄養が多くの微生物を育て、そしてこの微生物をエサにする昆虫などが集まり、さらにその昆虫などをエサにする生き物が集まるからです。また、毎年同じ場所、同じ時期に水を入れ、田植えや草取り、稲刈りなど、適度に人間の手が加わることで、特定の強い生き物だけが生き残ることを防ぎます。つまり、弱い生き物たちも生存できることとなり、結果としてさまざまな種類の生き物が生きていけるのです。\nまた、稲が青々と育っている水田の上を吹き抜ける風は、とても涼しくて気持ちがよいです。この風を「①青田風」といいます。水田の水面などから水分が空気中に蒸発するときに、周りの熱をうばいます。このとき空気が冷やされ、水田周辺の暑さをやわらげるため、水田の上を吹き抜ける風は涼しくなるのです。水田の周辺は、市街地に比べて気温が低いという調査結果もあります。\n水田には、私たちの食料である米を生産する場所としての役割のほかに、②さまざまな役割があり、人間やほかの動植物はその恵みを受けていると言えます。これから先も、水田がある環境を守っていくことが大切です。\n（注1）微生物：とても小さな生き物\n（注2）蒸発：水が気化する現象",
          "sentence": "問1：①青田風とはどのような風か。",
